const input = $json || {};
const headers = input.headers || {};
const body = input.body && typeof input.body === 'object' ? input.body : {};
function readHeader(name) {
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
  return key ? String(headers[key] || '') : '';
}
function env(name) { try { return String($env[name] || ''); } catch (error) { return ''; } }
function q(value) { return String(value ?? '').replace(/'/g, "''"); }
function sqlText(value) { return value === null || value === undefined || value === '' ? 'NULL' : "'" + q(value) + "'"; }
function fail(status, code, message) { return [{ json: { request_valid: false, http_status: status, code, message } }]; }
const expected = env('RENOV_INTERNAL_TOKEN');
const authorization = readHeader('authorization');
const bearer = authorization.match(/^Bearer\s+(.+)$/i)?.[1] || '';
const provided = readHeader('x-internal-token') || bearer;
if (!expected || provided !== expected) return fail(401, 'UNAUTHORIZED', 'Token interno invalido.');
const conversationId = String(body.conversation_id || '').trim();
if (!/^[0-9a-f-]{36}$/i.test(conversationId)) return fail(400, 'INVALID_CONVERSATION_ID', 'conversation_id debe ser UUID.');
const sourceMessageId = String(body.source_message_id || '').trim();
if (!sourceMessageId) return fail(400, 'SOURCE_MESSAGE_ID_REQUIRED', 'source_message_id es obligatorio para idempotencia.');
for (const forbidden of ['amount', 'price', 'payment_url', 'bendo_code', 'bank_account', 'qr']) {
  if (body[forbidden] !== undefined && body[forbidden] !== null && body[forbidden] !== '') {
    return fail(422, 'COMMERCIAL_DATA_NOT_ACCEPTED', 'WF-05 no acepta datos comerciales proporcionados por el caller.');
  }
}
const query = "SET search_path TO renovation_dev, public;\n" +
"WITH input AS (SELECT '" + q(conversationId) + "'::uuid AS conversation_id, " + sqlText(sourceMessageId) + "::text AS source_message_id, " + sqlText(body.sf_accountId) + "::text AS sf_account_id, " + sqlText(body.sf_vehicleId) + "::text AS sf_vehicle_id, " + sqlText(body.sf_contractId) + "::text AS sf_contract_id),\n" +
"resolved AS (SELECT c.id AS conversation_id, c.customer_id, c.status::text AS conversation_status, c.identity_verified, a.salesforce_contact_id, v.salesforce_vehicle_id, v.salesforce_contract_id, v.gps_status::text AS gps_status, v.opportunity_closed FROM input i LEFT JOIN conversations c ON c.id = i.conversation_id LEFT JOIN quicklink_account_assignments a ON a.id = c.customer_id LEFT JOIN quicklink_vehicle_assignments v ON v.customer_id = a.id AND v.deleted_at IS NULL AND (i.sf_vehicle_id IS NULL OR v.salesforce_vehicle_id = i.sf_vehicle_id))\n" +
"SELECT i.*, r.conversation_id::text, r.customer_id::text, r.conversation_status, r.identity_verified, r.salesforce_contact_id, r.salesforce_vehicle_id, r.salesforce_contract_id, r.gps_status, r.opportunity_closed, count(r.salesforce_vehicle_id) OVER ()::integer AS vehicle_match_count FROM input i LEFT JOIN resolved r ON true LIMIT 1;";
return [{ json: { request_valid: true, http_status: 200, source_message_id: sourceMessageId, resolve_sql: query } }];

const row = $json;
const request = row;
function result(status, code, action, reason, message) {
  return { http_status: status, code, action, handoff_reason: reason, client_message: message, payment_available: false };
}
let response;
if (!row.conversation_id) response = result(404, 'CONVERSATION_NOT_FOUND', 'handoff', 'billing', 'Con gusto, voy a gestionar su solicitud con nuestro equipo.');
else if (row.conversation_status !== 'bot_active') response = result(409, 'CONVERSATION_NOT_ACTIVE', 'silent', null, '');
else if (!(row.identity_verified === true || row.identity_verified === 't')) response = result(409, 'IDENTITY_NOT_VERIFIED', 'reply', null, 'Para proteger su información, primero debemos verificar su identidad.');
else if (Number(row.vehicle_match_count || 0) !== 1) response = result(422, 'VEHICLE_SELECTION_REQUIRED', 'handoff', 'billing', 'Con gusto, voy a gestionar su solicitud con nuestro equipo.');
else if (row.opportunity_closed === true || row.opportunity_closed === 't') response = result(409, 'OPPORTUNITY_CLOSED', 'silent', null, '');
else if (row.gps_status !== 'active') response = result(200, 'TECHNICAL_CHECK_REQUIRED', 'handoff', 'tech_support', 'Antes de realizar el pago es obligatorio coordinar un chequeo técnico para revisar o reactivar el equipo.');
else response = result(200, 'COMMERCIAL_CONTEXT_UNAVAILABLE', 'handoff', 'billing', 'Con gusto, voy a gestionar su solicitud con nuestro equipo.');
function q(value) { return String(value ?? '').replace(/'/g, "''"); }
const auditPayload = { workflow: 'REN-DEV-WF-05', code: response.code, payment_available: false, salesforce_account_id: row.salesforce_contact_id || null, salesforce_vehicle_id: row.salesforce_vehicle_id || null, salesforce_contract_id: row.salesforce_contract_id || null };
const logSql = "SET search_path TO renovation_dev, public; INSERT INTO interaction_logs (customer_id, conversation_id, event_type, correlation_id, payload, success, error_message) SELECT "
  + (row.customer_id ? "'" + q(row.customer_id) + "'::uuid" : 'NULL') + ", "
  + (row.conversation_id ? "'" + q(row.conversation_id) + "'::uuid" : 'NULL') + ", 'wf05_payment_blocked', '" + q(request.source_message_id) + "', '" + q(JSON.stringify(auditPayload)) + "'::jsonb, true, NULL WHERE NOT EXISTS (SELECT 1 FROM interaction_logs WHERE event_type = 'wf05_payment_blocked' AND correlation_id = '" + q(request.source_message_id) + "') RETURNING id;";
return [{ json: { ...request, ...response, log_sql: logSql } }];
